const row = $input.first().json;

let content = row.approved_content;

if (typeof content === 'string') {
  try {
    content = JSON.parse(content);
  } catch {
    throw new Error(
      'The approved campaign package contains invalid JSON.'
    );
  }
}

if (!content || typeof content !== 'object') {
  throw new Error(
    'The approved campaign package is missing.'
  );
}

const ads = Array.isArray(content.ads)
  ? content.ads
  : [];

const images = Array.isArray(content.image_prompts)
  ? content.image_prompts
  : [];

const videos = Array.isArray(content.video_concepts)
  ? content.video_concepts
  : [];

if (
  ads.length !== 3 ||
  images.length !== 3 ||
  videos.length !== 2
) {
  throw new Error(
    'The approved package does not contain the expected 3 ads, 3 image prompts, and 2 video concepts.'
  );
}

function clean(value) {
  return String(value ?? '').trim();
}

function taskKey(type, sourceId) {
  return [
    row.campaign_code,
    `V${row.approved_version_number}`,
    type,
    sourceId,
  ].join(':');
}

const tasks = [];

/**
 * Three copy-production tasks.
 */
for (const ad of ads) {
  tasks.push({
    task_key: taskKey('AD-COPY', ad.ad_id),

    task_type: 'ad_copy',

    title:
      `[${row.campaign_code}] ${ad.ad_id} — ${clean(ad.headline)}`,

    description: `
## Campaign

- Campaign: ${row.campaign_code}
- Company: ${row.company_name}
- Approved version: ${row.approved_version_number}
- Advertising angle: ${clean(ad.angle_id)}

## Primary text

${clean(ad.primary_text)}

## Headline

${clean(ad.headline)}

## Description

${clean(ad.description)}

## Call to action

${clean(ad.call_to_action)}

## Production requirement

Review formatting, spelling, claim accuracy, and Meta Ads suitability before marking complete.
`.trim(),

    metadata: {
      source_type: 'ad',
      source_id: ad.ad_id,
      angle_id: ad.angle_id,
      approved_version:
        Number(row.approved_version_number),
    },
  });
}

/**
 * Three static-image tasks.
 */
for (const image of images) {
  tasks.push({
    task_key: taskKey(
      'IMAGE-CREATIVE',
      image.prompt_id
    ),

    task_type: 'image_creative',

    title:
      `[${row.campaign_code}] ${image.prompt_id} — ${clean(image.concept_name)}`,

    description: `
## Campaign

- Campaign: ${row.campaign_code}
- Company: ${row.company_name}
- Approved version: ${row.approved_version_number}
- Advertising angle: ${clean(image.angle_id)}

## Creative concept

${clean(image.concept_name)}

## AI image prompt

${clean(image.prompt)}

## Suggested overlay text

${clean(image.overlay_text)}

## Production requirement

Generate or design the static creative, confirm that it matches the supplied product facts, and avoid invented logos, reviews, awards, or results.
`.trim(),

    metadata: {
      source_type: 'image_prompt',
      source_id: image.prompt_id,
      angle_id: image.angle_id,
      approved_version:
        Number(row.approved_version_number),
    },
  });
}

/**
 * Two video-production tasks.
 */
for (const video of videos) {
  const scenes = Array.isArray(video.scene_plan)
    ? video.scene_plan
        .map(
          (scene, index) =>
            `${index + 1}. ${clean(scene)}`
        )
        .join('\n')
    : '';

  tasks.push({
    task_key: taskKey(
      'VIDEO-CREATIVE',
      video.concept_id
    ),

    task_type: 'video_creative',

    title:
      `[${row.campaign_code}] ${video.concept_id} — ${clean(video.concept_name)}`,

    description: `
## Campaign

- Campaign: ${row.campaign_code}
- Company: ${row.company_name}
- Approved version: ${row.approved_version_number}
- Advertising angle: ${clean(video.angle_id)}
- Target duration: ${video.duration_seconds} seconds

## Opening hook

${clean(video.opening_hook)}

## Scene plan

${scenes}

## Voiceover

${clean(video.voiceover)}

## End card

${clean(video.end_card_text)}

## Production requirement

Create the short-form video, preserve the approved facts and wording, and complete a final quality review before delivery.
`.trim(),

    metadata: {
      source_type: 'video_concept',
      source_id: video.concept_id,
      angle_id: video.angle_id,
      duration_seconds: video.duration_seconds,
      approved_version:
        Number(row.approved_version_number),
    },
  });
}

/**
 * Final campaign-wide quality check.
 */
tasks.push({
  task_key: taskKey(
    'QUALITY-CHECK',
    'FINAL'
  ),

  task_type: 'quality_check',

  title:
    `[${row.campaign_code}] Final campaign quality and compliance check`,

  description: `
## Review the complete production package

Confirm:

1. Every asset uses the approved campaign version.
2. No unsupported product claims were added.
3. No invented testimonials, guarantees, awards, or statistics appear.
4. The offer and call to action match the approved brief.
5. Copy, static creatives, and videos use consistent branding.
6. All required assets are complete.
7. Links and file permissions work.
8. The campaign is ready for final delivery.

Approved by: ${clean(row.reviewer_name)}
Approval feedback: ${clean(row.approval_feedback) || 'No additional approval feedback.'}
`.trim(),

  metadata: {
    source_type: 'quality_check',
    source_id: 'FINAL',
    approved_version:
      Number(row.approved_version_number),
  },
});

const dbPayload = {
  job_id: row.job_id,
  campaign_id: row.campaign_id,
  campaign_code: row.campaign_code,
  campaign_version_id:
    row.campaign_version_id,
  approval_id: row.approval_id,
  tasks,
};

return [
  {
    json: {
      ...row,
      task_count: tasks.length,
      production_tasks: tasks,
      db_payload: dbPayload,
    },
  },
];
